class Solution:
    def maximumSubarrayXOR(self, nums, k):
        n = len(nums); ans = 0
        for i in range(n):
            x = 0; mx = mn = nums[i]
            for j in range(i, n):
                mx = max(mx, nums[j]); mn = min(mn, nums[j])
                if mx - mn > k: break
                x ^= nums[j]
                ans = max(ans, x)
        return ans

