from collections import deque
class Solution:
    def maximumSubarrayXOR(self, nums, k):
        ch = [[-1, -1]]; cnt = [0]
        def insert(x, d):
            node = 0; cnt[0] += d
            for b in range(14, -1, -1):
                bit = (x >> b) & 1
                if ch[node][bit] == -1:
                    ch.append([-1, -1]); cnt.append(0); ch[node][bit] = len(ch) - 1
                node = ch[node][bit]; cnt[node] += d
        def query(x):
            node = 0; res = 0
            for b in range(14, -1, -1):
                bit = (x >> b) & 1
                alt = ch[node][bit ^ 1]
                if alt != -1 and cnt[alt] > 0:
                    res |= 1 << b; node = alt
                else:
                    node = ch[node][bit]
            return res
        dqmx, dqmn = deque(), deque()
        pre = ans = left = 0
        insert(0, 1)
        for i, x in enumerate(nums):
            while dqmx and nums[dqmx[-1]] <= x: dqmx.pop()
            dqmx.append(i)
            while dqmn and nums[dqmn[-1]] >= x: dqmn.pop()
            dqmn.append(i)
            while nums[dqmx[0]] - nums[dqmn[0]] > k:
                insert(pre, -1); left += 1
                if dqmx[0] < left: dqmx.popleft()
                if dqmn[0] < left: dqmn.popleft()
            pre ^= x
            ans = max(ans, query(pre))
        return ans

