class Solution {
public:
    int maximumSubarrayXOR(vector<int>& nums, int k) {
        int n = nums.size();
        vector<array<int,2>> ch(1, {-1, -1});
        vector<int> cnt(1, 0);
        auto insert = [&](int x, int d) {
            int node = 0; cnt[0] += d;
            for (int b = 14; b >= 0; b--) {
                int bit = (x >> b) & 1;
                if (ch[node][bit][0] == -1 && ch[node][bit][1] == -1 && ch[node][bit][0] != 0) {}
                if (ch[node][bit] == -1) { ch.push_back({-1, -1}); cnt.push_back(0); ch[node][bit] = ch.size() - 1; }
                node = ch[node][bit]; cnt[node] += d;
            }
        };
        auto query = [&](int x) {
            int node = 0, res = 0;
            for (int b = 14; b >= 0; b--) {
                int bit = (x >> b) & 1;
                int alt = ch[node][bit ^ 1];
                if (alt != -1 && cnt[alt] > 0) { res |= 1 << b; node = alt; }
                else node = ch[node][bit];
            }
            return res;
        };
        deque<int> dqmx, dqmn;
        int pre = 0, ans = 0, left = 0;
        insert(0, 1);
        for (int i = 0; i < n; i++) {
            while (!dqmx.empty() && nums[dqmx.back()] <= nums[i]) dqmx.pop_back();
            dqmx.push_back(i);
            while (!dqmn.empty() && nums[dqmn.back()] >= nums[i]) dqmn.pop_back();
            dqmn.push_back(i);
            while (nums[dqmx.front()] - nums[dqmn.front()] > k) {
                insert(pre, -1); left++;
                if (dqmx.front() < left) dqmx.pop_front();
                if (dqmn.front() < left) dqmn.pop_front();
            }
            pre ^= nums[i];
            ans = max(ans, query(pre));
        }
        return ans;
    }
};

