class Solution {
    private int[][] ch = new int[700001][2];
    private int[] cnt = new int[700001];
    private int sz = 1;
    private void insert(int x, int d) {
        int node = 0; cnt[0] += d;
        for (int b = 14; b >= 0; b--) {
            int bit = (x >> b) & 1;
            if (ch[node][bit] == 0) { ch[sz][0] = 0; ch[sz][1] = 0; ch[node][bit] = sz++; }
            node = ch[node][bit]; cnt[node] += d;
        }
    }
    private int query(int x) {
        int node = 0, res = 0;
        for (int b = 14; b >= 0; b--) {
            int bit = (x >> b) & 1;
            int alt = ch[node][bit ^ 1];
            if (alt != 0 && cnt[alt] > 0) { res |= 1 << b; node = alt; }
            else node = ch[node][bit];
        }
        return res;
    }
    public int maximumSubarrayXOR(int[] nums, int k) {
        int n = nums.length, pre = 0, ans = 0, left = 0;
        ArrayDeque<Integer> dqmx = new ArrayDeque<>(), dqmn = new ArrayDeque<>();
        insert(0, 1);
        for (int i = 0; i < n; i++) {
            while (!dqmx.isEmpty() && nums[dqmx.peekLast()] <= nums[i]) dqmx.pollLast();
            dqmx.addLast(i);
            while (!dqmn.isEmpty() && nums[dqmn.peekLast()] >= nums[i]) dqmn.pollLast();
            dqmn.addLast(i);
            while (nums[dqmx.peekFirst()] - nums[dqmn.peekFirst()] > k) {
                insert(pre, -1); left++;
                if (dqmx.peekFirst() < left) dqmx.pollFirst();
                if (dqmn.peekFirst() < left) dqmn.pollFirst();
            }
            pre ^= nums[i];
            ans = Math.max(ans, query(pre));
        }
        return ans;
    }
}

